for(const k of['pen','line','eraser'])$(k).onclick=()=>{mode=k;tools()};
$('undo').onclick=()=>{const m=model();if(m.strokes.length){m.redo.push(m.strokes.pop());stamp(current().id);paint(editorSvg,current());tools()}};$('redo').onclick=()=>{const m=model();if(m.redo.length){m.strokes.push(m.redo.pop());stamp(current().id);paint(editorSvg,current());tools()}};$('save').onclick=async()=>{clearTimeout(timer);await flushAll();poll()};
window.addEventListener('online',()=>{flushAll();poll()});window.addEventListener('beforeunload',e=>{if(drawing||Object.values(models).some(m=>m.pending)){e.preventDefault();e.returnValue=''}});if(!key)status('Откройте полную ссылку для сохранения.','error');document.querySelector('.gallery').href='https://tools.pavljenko.ru/nor-gallery';render();poll();
